{
  "findings": [
    {
      "check_id": "CKV_AZURE_41",
      "title": "Ensure that the expiration date is set on all secrets",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "MEDIUM",
      "explanation": "The secret does not define an 'expiration_date', which means it will never expire. This violates security best practices for credential rotation and limits the blast radius if the secret is compromised."
    },
    {
      "check_id": "CKV_AZURE_114",
      "title": "Ensure that key vault secrets have \"content_type\" set",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "LOW",
      "explanation": "The 'content_type' attribute is missing. While not a direct security vulnerability, setting it (e.g., to 'text/plain') improves metadata consistency and helps consumers correctly interpret the secret's format."
    }
  ],
  "patched_code": "resource \"azurerm_key_vault_secret\" \"database_connection_string\" {\n  name          = \"database-connection-string\"\n  value         = \"Server=tcp:${azurerm_mssql_server.legal_sql_server.fully_qualified_domain_name},1433;Database=${azurerm_mssql_database.legal_metadata_db.name};User ID=${var.sql_admin_username};Password=${var.sql_admin_password};Encrypt=true;TrustServerCertificate=false;Connection Timeout=30;\"\n  key_vault_id  = azurerm_key_vault.legal_keyvault.id\n  content_type  = \"text/plain\"\n  expiration_date = timeadd(timestamp(), \"8760h\") # Expires in 1 year\n  depends_on    = [azurerm_mssql_database.legal_metadata_db]\n}",
  "fix_summary": "Added 'content_type' to specify the secret format and 'expiration_date' using 'timeadd' to enforce a 1-year rotation policy, addressing both Checkov findings."
}
